package com.german_software_engineers.trainerappmodel.Model;

import com.german_software_engineers.trainerappmodel.Enumerations.TrainingsTypes;
import com.german_software_engineers.trainerappmodel.Legacy.Schedule;

import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.io.File;
import java.io.FileWriter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class XMLParserTest {
    @Rule
    public TemporaryFolder temporaryFolder = new TemporaryFolder();

    @Test
    public void trainingsTypeSurvivesXmlRoundTrip() throws Exception {
        Model sourceModel = new Model();
        Schedule sourceSchedule = new Schedule("Strength");
        sourceSchedule.setTrainingsType(TrainingsTypes.pyramid_training);
        sourceModel.addSchedule(sourceSchedule);

        File file = temporaryFolder.newFile("schedule.xml");
        assertTrue(new XMLParser(sourceModel).writeFile(file));

        Model restoredModel = new Model();
        assertTrue(new XMLParser(restoredModel).parseFile(file));

        assertEquals(TrainingsTypes.pyramid_training,
                restoredModel.getSchedule("Strength").getTrainingsType());
    }

    @Test
    public void xmlWithoutTrainingsTypeUsesSpinnerDefault() throws Exception {
        File file = temporaryFolder.newFile("legacy-schedule.xml");
        FileWriter writer = new FileWriter(file);
        writer.write("<trainingsschedule appversion=\"1902\">"
                + "<schedule name=\"Legacy\" repetitions=\"1\" pause=\"2\" sets=\"3\" speed=\"4\"/>"
                + "</trainingsschedule>");
        writer.close();

        Model model = new Model();
        assertTrue(new XMLParser(model).parseFile(file));

        assertEquals(TrainingsTypes.strength_endurance,
                model.getSchedule("Legacy").getTrainingsType());
    }
}

